// Build a beautiful HTML email from the KPI digest payload.
const payload = $input.first().json.body;
const kpis = payload.kpis ?? [];
const recipientEmail = payload.recipientEmail ?? payload.email;
const userName = payload.userName ?? payload.name ?? 'Valued Client';
const weekOf = payload.weekOf ?? new Date().toISOString().slice(0, 10);

const rows = kpis.map(k => {
  const statusColor = k.status === 'ok' ? '#16a34a' : k.status === 'warn' ? '#d97706' : '#dc2626';
  const trend = k.trend === 'up' ? '↑' : k.trend === 'down' ? '↓' : '→';
  return `<tr>
    <td style="padding:8px 12px;border-bottom:1px solid #e2e8f0">${k.label}</td>
    <td style="padding:8px 12px;border-bottom:1px solid #e2e8f0;font-weight:bold;color:${statusColor}">${k.value}</td>
    <td style="padding:8px 12px;border-bottom:1px solid #e2e8f0;color:#64748b">${k.target ?? '—'}</td>
    <td style="padding:8px 12px;border-bottom:1px solid #e2e8f0">${trend}</td>
  </tr>`;
}).join('');

const html = `<!DOCTYPE html>
<html>
<body style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;padding:20px;color:#1e293b">
  <div style="background:linear-gradient(135deg,#1e3a5f,#0ea5e9);padding:24px;border-radius:12px 12px 0 0;color:white">
    <h1 style="margin:0;font-size:22px">📊 Weekly KPI Digest</h1>
    <p style="margin:8px 0 0;opacity:0.85">Week of ${weekOf}</p>
  </div>
  <div style="border:1px solid #e2e8f0;border-top:none;padding:24px;border-radius:0 0 12px 12px">
    <p>Dear ${userName},</p>
    <p>Here is your supply chain performance summary for the week:</p>
    <table style="width:100%;border-collapse:collapse;font-size:14px">
      <thead>
        <tr style="background:#f8fafc">
          <th style="padding:8px 12px;text-align:left;color:#64748b;font-weight:600">KPI</th>
          <th style="padding:8px 12px;text-align:left;color:#64748b;font-weight:600">Value</th>
          <th style="padding:8px 12px;text-align:left;color:#64748b;font-weight:600">Target</th>
          <th style="padding:8px 12px;text-align:left;color:#64748b;font-weight:600">Trend</th>
        </tr>
      </thead>
      <tbody>${rows}</tbody>
    </table>
    <div style="margin-top:24px;text-align:center">
      <a href="https://YOUR_ISC_DOMAIN/" style="background:#0ea5e9;color:white;padding:12px 24px;border-radius:8px;text-decoration:none;font-weight:bold">View Full Dashboard →</a>
    </div>
    <p style="color:#94a3b8;font-size:12px;margin-top:24px">You are receiving this because you are subscribed to weekly KPI digests. <a href="https://YOUR_ISC_DOMAIN/settings">Manage preferences</a>.</p>
  </div>
</body>
</html>`;

return [{ json: { html, recipientEmail, userName, weekOf } }];
